-- =========================================================
-- HORS-SÉRIE — RECONSTRUCTION DU RÉFÉRENTIEL PÉDAGOGIQUE CP À CM2
-- Date : 2026-07-30
--
-- Ce fichier n'appartient PAS à la numérotation historique des migrations.
-- Il aligne la base sur la structure désormais retenue :
--
--   discipline > domaine > thème > objectif d'apprentissage
--              > dossier de niveau > activités
--
-- Sources :
-- - _infos/referentiels/arborescence-mathematiques-cp-cm2.txt
-- - _infos/referentiels/arborescence-francais-cp-cm2.txt
-- - _infos/referentiels/graphemes-base.txt
--
-- IMPORTANT :
-- - le script reconstruit entièrement pedagogical_nodes ;
-- - les liens actuels des activités sont sauvegardés ;
-- - les 26 activités du catalogue local historique sont reclassées ;
-- - toute autre activité est conservée dans une branche inactive
--   « À reclasser (migration) » ;
-- - le système spécial des blocs de progression de l'étude du code
--   sera ajouté dans un patch Aventure ultérieur.
-- =========================================================

begin;

do $$
begin
  if to_regclass('public.pedagogical_nodes') is null then
    raise exception 'Table public.pedagogical_nodes introuvable. Exécute d’abord les migrations 13 et 14.';
  end if;
  if to_regclass('public.catalog_activities') is null then
    raise exception 'Table public.catalog_activities introuvable.';
  end if;
  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'catalog_activities'
      and column_name = 'pedagogical_node_id'
  ) then
    raise exception 'Colonne catalog_activities.pedagogical_node_id introuvable.';
  end if;
end;
$$;

-- Sauvegardes de sécurité conservées après exécution.
create table if not exists public.pedagogical_nodes_backup_before_level_folders_20260730 (
  pedagogical_node_id text primary key,
  row_data jsonb not null,
  backed_up_at timestamptz not null default now()
);

select pn.id, to_jsonb(pn)
from public.pedagogical_nodes pn
on conflict (pedagogical_node_id) do nothing;

create table if not exists public.catalog_activity_node_backup_before_level_folders_20260730 (
  catalog_activity_id text primary key,
  pedagogical_node_id text,
  backed_up_at timestamptz not null default now()
);

select id, pedagogical_node_id
from public.catalog_activities
on conflict (catalog_activity_id) do nothing;

-- Retrait temporaire des garde-fous qui empêchent la reconstruction.
drop trigger if exists trg_validate_pedagogical_node_tree on public.pedagogical_nodes;
drop trigger if exists trg_validate_catalog_folder_tree on public.pedagogical_nodes;
drop trigger if exists trg_validate_catalog_activity_grade_folder on public.catalog_activities;

drop function if exists public.validate_pedagogical_node_tree();
drop function if exists public.validate_catalog_folder_tree();
drop function if exists public.validate_catalog_activity_grade_folder();

do $$
declare
  constraint_name text;
begin
  for constraint_name in
    select pc.conname
    from pg_constraint pc
    join pg_class rel on rel.oid = pc.conrelid
    join pg_namespace ns on ns.oid = rel.relnamespace
    where ns.nspname = 'public'
      and rel.relname = 'catalog_activities'
      and pc.contype = 'f'
      and pg_get_constraintdef(pc.oid) like '%pedagogical_node_id%'
  loop
    execute format('alter table public.catalog_activities drop constraint %I', constraint_name);
  end loop;
end;
$$;

do $$
declare
  constraint_name text;
begin
  for constraint_name in
    select conname
    from pg_constraint
    where conrelid = 'public.pedagogical_nodes'::regclass
      and conname in (
        'catalog_folders_type_check',
        'pedagogical_nodes_type_check',
        'catalog_folders_scope_mode_check',
        'pedagogical_nodes_scope_mode_check',
        'catalog_folders_grade_levels_check',
        'pedagogical_nodes_grade_levels_check',
        'catalog_folders_root_scope_check',
        'pedagogical_nodes_root_scope_check',
        'pedagogical_nodes_grade_folder_name_check'
      )
  loop
    execute format('alter table public.pedagogical_nodes drop constraint %I', constraint_name);
  end loop;
end;
$$;

-- Les anciennes portées de niveaux sont remplacées par de vrais dossiers.
alter table public.pedagogical_nodes
  drop column if exists grade_scope_mode,
  drop column if exists grade_levels;

create temporary table pedagogical_seed (
  id text primary key,
  parent_id text,
  name text not null,
  node_type text not null,
  display_order integer not null,
  is_active boolean not null
) on commit drop;


-- L'ancienne arborescence peut maintenant être remplacée sans perdre les activités.
truncate table public.pedagogical_nodes;

select id, parent_id, name, node_type, display_order, is_active
from pedagogical_seed
order by
  case node_type
    when 'discipline' then 1
    when 'domain' then 2
    when 'theme' then 3
    when 'learning_objective' then 4
    when 'grade_level' then 5
    else 99
  end,
  display_order,
  id;

-- Reclassement explicite des activités historiques connues.
create temporary table catalog_activity_seed_mapping (
  catalog_activity_id text primary key,
  pedagogical_node_id text not null
) on commit drop;


update public.catalog_activities ca
set pedagogical_node_id = m.pedagogical_node_id
from catalog_activity_seed_mapping m
where ca.id = m.catalog_activity_id;

-- Toute activité non reconnue est préservée dans une branche inactive.
update public.catalog_activities ca
set pedagogical_node_id = 'migration-reclassement.o.activites-a-reclasser.ce1'
where not exists (
  select 1
  from catalog_activity_seed_mapping m
  where m.catalog_activity_id = ca.id
);

-- Contraintes du nouveau modèle.
alter table public.pedagogical_nodes
  add constraint pedagogical_nodes_type_check
  check (node_type in ('discipline', 'domain', 'theme', 'learning_objective', 'grade_level'));

alter table public.pedagogical_nodes
  add constraint pedagogical_nodes_grade_folder_name_check
  check (
    node_type <> 'grade_level'
    or name in ('CP', 'CE1', 'CE2', 'CM1', 'CM2')
  );

drop index if exists public.pedagogical_nodes_parent_name_unique_idx;
create unique index pedagogical_nodes_parent_name_unique_idx
on public.pedagogical_nodes (coalesce(parent_id, ''), lower(name));

create or replace function public.validate_pedagogical_node_tree()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  parent_type text;
  cursor_id text;
begin
  if new.parent_id = new.id then
    raise exception 'Un nœud pédagogique ne peut pas être son propre parent.';
  end if;

  if new.parent_id is null then
    if new.node_type <> 'discipline' then
      raise exception 'Seules les disciplines peuvent être placées à la racine.';
    end if;
    return new;
  end if;

  select node_type
  into parent_type
  from public.pedagogical_nodes
  where id = new.parent_id;

  if parent_type is null then
    raise exception 'Le parent pédagogique % est introuvable.', new.parent_id;
  end if;

  if not (
    (parent_type = 'discipline' and new.node_type = 'domain')
    or (parent_type = 'domain' and new.node_type = 'theme')
    or (parent_type = 'theme' and new.node_type = 'learning_objective')
    or (parent_type = 'learning_objective' and new.node_type = 'grade_level')
  ) then
    raise exception 'Hiérarchie invalide : % ne peut pas contenir %.', parent_type, new.node_type;
  end if;

  if new.node_type = 'grade_level'
     and new.name not in ('CP', 'CE1', 'CE2', 'CM1', 'CM2') then
    raise exception 'Dossier de niveau invalide : %.', new.name;
  end if;

  cursor_id := new.parent_id;
  while cursor_id is not null loop
    if cursor_id = new.id then
      raise exception 'Ce déplacement créerait une boucle dans l’arborescence.';
    end if;
    select parent_id into cursor_id
    from public.pedagogical_nodes
    where id = cursor_id;
  end loop;

  return new;
end;
$$;

create trigger trg_validate_pedagogical_node_tree
before insert or update of parent_id, node_type, name
on public.pedagogical_nodes
for each row execute function public.validate_pedagogical_node_tree();

create or replace function public.validate_catalog_activity_grade_folder()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  target_type text;
begin
  select node_type
  into target_type
  from public.pedagogical_nodes
  where id = new.pedagogical_node_id;

  if target_type is distinct from 'grade_level' then
    raise exception 'Une activité doit être rangée dans un dossier de niveau CP, CE1, CE2, CM1 ou CM2.';
  end if;

  return new;
end;
$$;

create trigger trg_validate_catalog_activity_grade_folder
before insert or update of pedagogical_node_id
on public.catalog_activities
for each row execute function public.validate_catalog_activity_grade_folder();

alter table public.catalog_activities
  add constraint catalog_activities_pedagogical_node_fk
  foreign key (pedagogical_node_id)
  references public.pedagogical_nodes(id)
  on update cascade
  on delete restrict;

create index if not exists pedagogical_nodes_parent_order_idx
on public.pedagogical_nodes (parent_id, display_order, name);

create index if not exists pedagogical_nodes_active_idx
on public.pedagogical_nodes (is_active);

-- Vérifications finales.
do $$
declare
  orphan_count bigint;
  invalid_activity_target_count bigint;
  invalid_grade_count bigint;
begin
  select count(*)
  into orphan_count
  from public.catalog_activities ca
  left join public.pedagogical_nodes pn on pn.id = ca.pedagogical_node_id
  where pn.id is null;

  if orphan_count <> 0 then
    raise exception 'Reconstruction annulée : % activité(s) orpheline(s).', orphan_count;
  end if;

  select count(*)
  into invalid_activity_target_count
  from public.catalog_activities ca
  join public.pedagogical_nodes pn on pn.id = ca.pedagogical_node_id
  where pn.node_type <> 'grade_level';

  if invalid_activity_target_count <> 0 then
    raise exception 'Reconstruction annulée : % activité(s) ne sont pas rangées dans un dossier de niveau.', invalid_activity_target_count;
  end if;

  select count(*)
  into invalid_grade_count
  from public.pedagogical_nodes
  where node_type = 'grade_level'
    and name not in ('CP', 'CE1', 'CE2', 'CM1', 'CM2');

  if invalid_grade_count <> 0 then
    raise exception 'Reconstruction annulée : % dossier(s) de niveau invalide(s).', invalid_grade_count;
  end if;
end;
$$;

commit;
